-- APY-02: private, source-aware foundation. No Apple/CAL adapter is enabled.
BEGIN;
LOCK TABLE public.transactions IN EXCLUSIVE MODE;

CREATE TABLE IF NOT EXISTS public.transaction_ingestion_sources (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source_kind TEXT NOT NULL CHECK (source_kind IN ('apple_pay','cal','legacy_api','file_import')),
  instance_key TEXT NOT NULL CHECK (length(instance_key) BETWEEN 1 AND 255 AND instance_key=btrim(instance_key)),
  is_active BOOLEAN NOT NULL DEFAULT true,
  revision BIGINT NOT NULL DEFAULT 1 CHECK (revision>0),
  configuration JSONB NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(configuration)='object' AND octet_length(configuration::text)<=32768),
  created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
  UNIQUE(source_kind,instance_key)
);
CREATE TABLE IF NOT EXISTS public.transaction_source_observations (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source_id BIGINT NOT NULL REFERENCES public.transaction_ingestion_sources(id) ON DELETE RESTRICT,
  idempotency_key TEXT COLLATE "C" NOT NULL,
  provider_reference JSONB,
  transaction_id INTEGER REFERENCES public.transactions(id) ON DELETE RESTRICT,
  evidence_origin TEXT NOT NULL CHECK (evidence_origin IN ('source','legacy_backfill','legacy_insert')),
  accepted_payload JSONB NOT NULL,
  payload_fingerprint TEXT NOT NULL CHECK (length(payload_fingerprint)=64),
  normalization_version INTEGER NOT NULL DEFAULT 1 CHECK (normalization_version=1),
  source_revision BIGINT NOT NULL,
  merchant TEXT CHECK (length(merchant)<=512),
  normalized_merchant TEXT,
  merchant_key TEXT,
  amount_minor NUMERIC(30,0),
  currency_code TEXT,
  amount_basis TEXT,
  movement_type TEXT,
  source_transaction_date DATE,
  date_discrepancy BOOLEAN NOT NULL DEFAULT false,
  source_charge_date DATE,
  occurred_at TIMESTAMPTZ,
  occurred_at_raw TEXT,
  time_precision TEXT,
  time_width INTERVAL,
  time_verified BOOLEAN NOT NULL DEFAULT false,
  reference_verified BOOLEAN NOT NULL DEFAULT false,
  observed_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
  payment_source_id BIGINT REFERENCES public.payment_sources(id) ON DELETE RESTRICT,
  source_metadata JSONB NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(source_metadata)='object' AND octet_length(source_metadata::text)<=8192),
  outcome TEXT NOT NULL CHECK (outcome IN ('created','reconciled','ambiguous','conflict','legacy_unverified')),
  reason_code TEXT NOT NULL,
  review_required BOOLEAN NOT NULL DEFAULT false,
  decision_revision BIGINT NOT NULL DEFAULT 1 CHECK (decision_revision>0),
  candidate_ids INTEGER[] NOT NULL DEFAULT '{}',
  initial_identity JSONB,
  charge_date_origin TEXT,
  identity_overridden BOOLEAN NOT NULL DEFAULT false,
  charge_date_overridden BOOLEAN NOT NULL DEFAULT false,
  UNIQUE(source_id,idempotency_key),
  CHECK (length(idempotency_key)>0 AND (evidence_origin<>'source' OR length(idempotency_key)<=255)),
  CHECK (provider_reference IS NULL OR (jsonb_typeof(provider_reference)='object' AND octet_length(provider_reference::text)<=2048)),
  CHECK (evidence_origin<>'source' OR (amount_minor IS NOT NULL AND amount_minor>0
    AND currency_code IS NOT NULL AND currency_code='ILS' AND amount_basis IS NOT NULL AND amount_basis='accounting'
    AND movement_type IS NOT NULL AND movement_type IN ('expense','income') AND source_transaction_date IS NOT NULL AND payment_source_id IS NOT NULL
    AND merchant IS NOT NULL AND normalized_merchant IS NOT NULL AND normalized_merchant<>'')),
  CHECK (outcome NOT IN ('created','reconciled') OR transaction_id IS NOT NULL),
  CHECK (cardinality(candidate_ids)<=100)
);
CREATE INDEX IF NOT EXISTS idx_source_observation_candidates ON public.transaction_source_observations
 (payment_source_id,movement_type,currency_code,amount_minor,source_transaction_date);
CREATE INDEX IF NOT EXISTS idx_source_observation_transaction ON public.transaction_source_observations(transaction_id);
CREATE INDEX IF NOT EXISTS idx_source_observation_reference ON public.transaction_source_observations USING gin(provider_reference);
CREATE TABLE IF NOT EXISTS public.transaction_reconciliation_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source_id BIGINT NOT NULL REFERENCES public.transaction_ingestion_sources(id) ON DELETE RESTRICT,
  observation_id BIGINT REFERENCES public.transaction_source_observations(id) ON DELETE RESTRICT,
  event_kind TEXT NOT NULL CHECK (event_kind IN ('source_configuration','created','reconciled','ambiguous','conflict','amendment','review','cancel','user_edit','enrichment')),
  request_key UUID UNIQUE,
  command_fingerprint TEXT,
  decision_revision BIGINT,
  transaction_id INTEGER REFERENCES public.transactions(id) ON DELETE RESTRICT,
  actor TEXT NOT NULL,
  reason_code TEXT NOT NULL,
  evidence JSONB NOT NULL DEFAULT '{}' CHECK (octet_length(evidence::text)<=70000),
  result JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
  CHECK (event_kind='source_configuration' OR observation_id IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS idx_reconciliation_observation ON public.transaction_reconciliation_events(observation_id,id);

CREATE OR REPLACE FUNCTION public.apy_hash(p JSONB) RETURNS TEXT LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT encode(sha256(convert_to(p::text,'UTF8')),'hex');
$$;
CREATE OR REPLACE FUNCTION public.apy_keys(p JSONB, allowed TEXT[]) RETURNS VOID LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF p IS NULL OR jsonb_typeof(p)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p) k WHERE NOT k=ANY(allowed)) THEN
  RAISE EXCEPTION 'unsupported_field' USING ERRCODE='22023'; END IF;
END $$;
CREATE OR REPLACE FUNCTION public.apy_review_fingerprints(p_id BIGINT) RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT coalesce(jsonb_object_agg(t.id::text,md5(to_jsonb(t)::text)),'{}') FROM public.transactions t WHERE t.id IN (
 SELECT unnest(o.candidate_ids) FROM public.transaction_source_observations o WHERE o.id=p_id
 UNION SELECT other.transaction_id FROM public.transaction_source_observations o JOIN public.transaction_source_observations other
 ON other.payment_source_id=o.payment_source_id AND other.amount_minor=o.amount_minor AND other.movement_type=o.movement_type
 AND abs(other.source_transaction_date-o.source_transaction_date)<=1 AND (other.merchant_key=o.merchant_key OR other.normalized_merchant=o.normalized_merchant)
 WHERE o.id=p_id AND other.transaction_id IS NOT NULL);
$$;
CREATE OR REPLACE FUNCTION public.get_ingestion_observation(p_observation_id BIGINT) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN RETURN (SELECT public.apy_result(o.id)||jsonb_build_object('source_id',o.source_id::text,'idempotency_key',o.idempotency_key,
 'provider_reference',o.provider_reference,'occurred_at',o.occurred_at,'occurred_at_raw',o.occurred_at_raw,'time_precision',o.time_precision,'observed_at',o.observed_at,'date_discrepancy',o.date_discrepancy,
 'expected_transaction_fingerprint',public.apy_cash_fingerprint(o.transaction_id),'candidate_fingerprints',public.apy_review_fingerprints(o.id))
 FROM public.transaction_source_observations o WHERE o.id=p_observation_id); END;
$$;
CREATE OR REPLACE FUNCTION public.apy_payment_source(cfg JSONB,p JSONB) RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE chosen BIGINT; mapped BIGINT; candidates BIGINT[]; e JSONB=coalesce(p->'payment_evidence','{}');
BEGIN
 IF e->>'card_reference' IS NOT NULL THEN
  SELECT (x->>'payment_source_id')::bigint INTO mapped FROM jsonb_array_elements(coalesce(cfg->'card_mappings','[]')) x WHERE x->>'card_reference'=e->>'card_reference';
  IF mapped IS NULL THEN RAISE EXCEPTION 'payment_source_not_found' USING ERRCODE='22023'; END IF;
 END IF;
 chosen=(p->>'payment_source_id')::bigint;
 IF chosen IS NOT NULL AND mapped IS NOT NULL AND chosen<>mapped THEN RAISE EXCEPTION 'payment_source_conflict' USING ERRCODE='22023'; END IF;
 chosen=coalesce(chosen,mapped);
 IF chosen IS NULL AND e->>'last4' IS NULL THEN RAISE EXCEPTION 'payment_source_not_found' USING ERRCODE='22023'; END IF;
 SELECT array_agg(s.id ORDER BY s.id) INTO candidates FROM public.payment_sources s WHERE s.is_active
 AND coalesce(cfg->'payment_source_ids','[]') ? s.id::text AND (chosen IS NULL OR s.id=chosen)
 AND (e->>'last4' IS NULL OR s.last4=e->>'last4') AND (e->>'issuer' IS NULL OR s.issuer=e->>'issuer')
 AND (e->>'method' IS NULL OR s.method=e->>'method') AND (e->>'owner' IS NULL OR s.owner=e->>'owner') AND (e->>'name' IS NULL OR s.name=e->>'name');
 IF coalesce(cardinality(candidates),0)=0 THEN RAISE EXCEPTION 'payment_source_not_found' USING ERRCODE='22023'; END IF;
 IF cardinality(candidates)>1 THEN RAISE EXCEPTION 'payment_source_ambiguous' USING ERRCODE='22023'; END IF;
 PERFORM 1 FROM public.payment_sources WHERE id=candidates[1] AND is_active FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'payment_source_not_found' USING ERRCODE='22023'; END IF;
 RETURN candidates[1];
END $$;

CREATE OR REPLACE FUNCTION public.apy_charge_evidence(p_observation_id BIGINT) RETURNS DATE LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT coalesce((SELECT (e.evidence->>'charge_date')::date FROM public.transaction_reconciliation_events e
 WHERE e.observation_id=o.id AND e.event_kind='amendment' AND e.reason_code='charge_date_evidence' ORDER BY e.id DESC LIMIT 1),o.source_charge_date)
 FROM public.transaction_source_observations o WHERE o.id=p_observation_id;
$$;

CREATE OR REPLACE FUNCTION public.apy_create_cash(p_observation_id BIGINT) RETURNS INTEGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE o public.transaction_source_observations%ROWTYPE; t public.transactions%ROWTYPE; charge DATE;
BEGIN
 SELECT * INTO STRICT o FROM public.transaction_source_observations WHERE id=p_observation_id;
 IF o.transaction_id IS NOT NULL OR o.evidence_origin<>'source' THEN RAISE EXCEPTION 'observation_already_linked' USING ERRCODE='22023'; END IF;
 IF o.accepted_payload->>'category_id' IS NOT NULL THEN
  PERFORM 1 FROM public.categories WHERE id=(o.accepted_payload->>'category_id')::bigint AND is_active AND savings_role IS NULL AND type=o.movement_type FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'invalid_category' USING ERRCODE='22023'; END IF;
 END IF;
 PERFORM 1 FROM public.payment_sources WHERE id=o.payment_source_id AND is_active FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'payment_source_not_found' USING ERRCODE='22023'; END IF;
 charge=public.apy_charge_evidence(o.id);
 INSERT INTO public.transactions(description,total_amount,currency,movement_type,transaction_date,charge_date,payment_source_id,category_id)
 VALUES(o.merchant,o.amount_minor/100,'ILS',o.movement_type,o.source_transaction_date,coalesce(charge,o.source_transaction_date),o.payment_source_id,(o.accepted_payload->>'category_id')::bigint) RETURNING * INTO t;
 UPDATE public.transaction_source_observations SET transaction_id=t.id,initial_identity=public.apy_identity(t),charge_date_origin=CASE WHEN charge IS NULL THEN 'provisional_purchase_date' ELSE 'source_supplied' END WHERE id=o.id;
 RETURN t.id;
END $$;

CREATE OR REPLACE FUNCTION public.apy_enrich(p_observation_id BIGINT,p_charge_date DATE) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE o public.transaction_source_observations%ROWTYPE; creator public.transaction_source_observations%ROWTYPE; t public.transactions%ROWTYPE;
BEGIN
 SELECT * INTO STRICT o FROM public.transaction_source_observations WHERE id=p_observation_id;
 IF p_charge_date IS NULL THEN RETURN true; END IF;
 SELECT * INTO t FROM public.transactions WHERE id=o.transaction_id;
 IF t.id IS NULL OR t.voided_at IS NOT NULL THEN RETURN false; END IF;
 SELECT * INTO creator FROM public.transaction_source_observations WHERE transaction_id=t.id AND charge_date_origin IS NOT NULL ORDER BY id LIMIT 1;
 IF creator.id IS NULL OR public.apy_protected(t.id) OR public.apy_captured(t.id) OR creator.identity_overridden OR creator.charge_date_overridden THEN RETURN false; END IF;
 IF creator.charge_date_origin<>'provisional_purchase_date' THEN RETURN t.charge_date=p_charge_date; END IF;
 INSERT INTO public.transaction_reconciliation_events(source_id,observation_id,event_kind,transaction_id,actor,reason_code,evidence)
 VALUES(o.source_id,o.id,'enrichment',t.id,'source','provisional_charge_date',jsonb_build_object('charge_date',p_charge_date));
 UPDATE public.transactions SET charge_date=p_charge_date WHERE id=t.id;
 UPDATE public.transaction_source_observations SET charge_date_origin='cal_confirmed' WHERE id=creator.id;
 RETURN true;
END $$;

CREATE OR REPLACE FUNCTION public.ingest_observation(p_source_id BIGINT,p_observation JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
<<ingestion>>
DECLARE s public.transaction_ingestion_sources%ROWTYPE; old public.transaction_source_observations%ROWTYPE; o public.transaction_source_observations%ROWTYPE;
 n JSONB; p JSONB; hash TEXT; payment BIGINT; merchant_key TEXT; category BIGINT; ref_verified BOOLEAN; time_valid BOOLEAN;
 c RECORD; t public.transactions%ROWTYPE; candidates JSONB='{}'; entry JSONB; candidate_ids INTEGER[]='{}'; refs INTEGER[]='{}'; times INTEGER[]='{}'; unknowns INTEGER[]='{}';
 target INTEGER; reason TEXT; outcome TEXT; sentinel TEXT; strong_ref BOOLEAN; comparable BOOLEAN; compatible BOOLEAN; saturated BOOLEAN; v RECORD; count_candidates INTEGER;
BEGIN
 LOCK TABLE public.transactions IN EXCLUSIVE MODE;
 SELECT * INTO s FROM public.transaction_ingestion_sources WHERE id=p_source_id FOR UPDATE;
 IF NOT FOUND OR NOT s.is_active OR s.source_kind='legacy_api' THEN RETURN public.apy_rejected('source_unavailable'); END IF;
 BEGIN n=public.apy_normalize(p_observation);
 EXCEPTION WHEN SQLSTATE '22023' OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range THEN RETURN public.apy_rejected(CASE WHEN SQLSTATE='22023' THEN SQLERRM ELSE 'invalid_input' END); END;
 p=n->'input'; hash=public.apy_hash(p);
 SELECT * INTO old FROM public.transaction_source_observations WHERE source_id=s.id AND idempotency_key=p->>'idempotency_key' FOR UPDATE;
 IF FOUND THEN
  IF old.payload_fingerprint=hash THEN RETURN public.apy_result(old.id,true); END IF;
  INSERT INTO public.transaction_reconciliation_events(source_id,observation_id,event_kind,transaction_id,actor,reason_code,evidence)
  VALUES(s.id,old.id,'conflict',old.transaction_id,'source','idempotency_key_conflict',jsonb_build_object('received_fingerprint',hash));
  RETURN public.apy_result(old.id)||jsonb_build_object('outcome','conflict','review_required',true,'reason_code','idempotency_key_conflict');
 END IF;
 BEGIN
  payment=public.apy_payment_source(s.configuration,p); category=(p->>'category_id')::bigint;
  IF category IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.categories WHERE id=category AND is_active AND savings_role IS NULL AND type=p->>'movement_type') THEN RAISE EXCEPTION 'invalid_category' USING ERRCODE='22023'; END IF;
  IF category IS NOT NULL THEN
   PERFORM 1 FROM public.categories WHERE id=category AND is_active AND savings_role IS NULL AND type=p->>'movement_type' FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'invalid_category' USING ERRCODE='22023'; END IF;
  END IF;
 EXCEPTION WHEN SQLSTATE '22023' THEN RETURN public.apy_rejected(SQLERRM); END;
 SELECT 'alias:'||(a->>'key') INTO merchant_key FROM jsonb_array_elements(coalesce(s.configuration->'aliases','[]')) a
 WHERE public.apy_merchant(a->>'merchant')=n->>'merchant' AND (a->>'payment_source_id' IS NULL OR a->>'payment_source_id'=payment::text) LIMIT 1;
 merchant_key=coalesce(merchant_key,'raw:'||(n->>'merchant'));
 ref_verified=p->>'provider_reference' IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(s.configuration->'verified_references','[]')) r WHERE r=(p->'provider_reference')-'value');
 time_valid=coalesce((s.configuration->>'time_verified')::boolean,false) AND n->>'instant' IS NOT NULL;
 FOR c IN SELECT ob.*,other.source_kind FROM public.transaction_source_observations ob JOIN public.transaction_ingestion_sources other ON other.id=ob.source_id
 WHERE ob.evidence_origin='source' AND ob.transaction_id IS NOT NULL AND ((s.source_kind='apple_pay' AND other.source_kind='cal') OR (s.source_kind='cal' AND other.source_kind='apple_pay'))
 AND ((ob.payment_source_id=payment AND ob.amount_minor=(n->>'amount_minor')::numeric AND ob.currency_code='ILS' AND ob.amount_basis='accounting' AND ob.movement_type=p->>'movement_type'
 AND abs(ob.source_transaction_date-(n->>'date')::date)<=1 AND (ob.merchant_key=ingestion.merchant_key OR ob.normalized_merchant=n->>'merchant'))
 OR (ref_verified AND ob.reference_verified AND ob.provider_reference=p->'provider_reference')) ORDER BY ob.id LOOP
  SELECT * INTO t FROM public.transactions WHERE id=c.transaction_id;
  strong_ref=ref_verified AND c.reference_verified AND c.provider_reference=p->'provider_reference';
  comparable=time_valid AND c.time_verified AND c.occurred_at IS NOT NULL;
  compatible=comparable AND c.occurred_at<=(n->>'instant')::timestamptz+(n->>'width')::interval AND (n->>'instant')::timestamptz<=c.occurred_at+c.time_width;
  -- Distinct known times can identify separate purchases, including after an old void.
  IF comparable AND NOT compatible AND NOT strong_ref THEN CONTINUE; END IF;
  IF t.voided_at IS NOT NULL THEN sentinel='cancelled_record_exists';
  ELSIF public.apy_protected(t.id) THEN sentinel='protected_transaction';
  ELSIF c.identity_overridden OR c.initial_identity IS DISTINCT FROM public.apy_identity(t) THEN sentinel='identity_edited';
  ELSIF strong_ref AND (c.payment_source_id<>payment OR c.amount_minor<>(n->>'amount_minor')::numeric OR c.movement_type<>p->>'movement_type') THEN sentinel='reference_conflict'; END IF;
  saturated=EXISTS(SELECT 1 FROM public.transaction_source_observations ob WHERE ob.transaction_id=t.id AND ob.source_id=s.id);
  entry=coalesce(candidates->t.id::text,'{}');
  candidates=jsonb_set(candidates,ARRAY[t.id::text],jsonb_build_object('reference',coalesce((entry->>'reference')::boolean,false) OR (strong_ref AND abs(c.source_transaction_date-(n->>'date')::date)<=1 AND NOT saturated),
   'time',coalesce((entry->>'time')::boolean,false) OR (compatible AND NOT saturated),'unknown',coalesce((entry->>'unknown')::boolean,false) OR NOT comparable,
   'same_date',coalesce((entry->>'same_date')::boolean,false) OR c.source_transaction_date=(n->>'date')::date,'saturated',coalesce((entry->>'saturated')::boolean,false) OR saturated));
  IF (SELECT count(*) FROM jsonb_object_keys(candidates))>100 THEN EXIT; END IF;
 END LOOP;
 count_candidates=(SELECT count(*) FROM jsonb_object_keys(candidates));
 IF count_candidates>100 THEN outcome='ambiguous'; reason='candidate_overflow';
 ELSE
  FOR v IN SELECT * FROM jsonb_each(candidates) LOOP
   candidate_ids=array_append(candidate_ids,v.key::integer);
   IF (v.value->>'reference')::boolean THEN refs=array_append(refs,v.key::integer); END IF;
   IF (v.value->>'time')::boolean THEN times=array_append(times,v.key::integer); END IF;
   IF (v.value->>'unknown')::boolean THEN unknowns=array_append(unknowns,v.key::integer); END IF;
  END LOOP;
  IF sentinel IS NOT NULL THEN outcome='conflict';reason=sentinel;
  ELSIF cardinality(refs)=1 THEN target=refs[1];reason='verified_reference';
  ELSIF cardinality(refs)>1 THEN outcome='ambiguous';reason='competing_references';
  ELSIF cardinality(times)=1 AND NOT EXISTS(SELECT 1 FROM unnest(unknowns) id WHERE id<>times[1]) THEN target=times[1];reason='precision_time';
  ELSIF count_candidates=1 AND cardinality(unknowns)=1 AND (candidates->candidate_ids[1]::text->>'same_date')::boolean
   AND NOT (candidates->candidate_ids[1]::text->>'saturated')::boolean
   AND NOT EXISTS(SELECT 1 FROM public.transaction_source_observations pending WHERE pending.transaction_id IS NULL AND pending.evidence_origin='source' AND pending.payment_source_id=payment
    AND pending.amount_minor=(n->>'amount_minor')::numeric AND pending.movement_type=p->>'movement_type' AND abs(pending.source_transaction_date-(n->>'date')::date)<=1
    AND (pending.merchant_key=ingestion.merchant_key OR pending.normalized_merchant=n->>'merchant')) THEN target=candidate_ids[1];reason='unique_purchase_tuple';
  ELSIF count_candidates>0 THEN outcome='ambiguous';reason='competing_candidates';
  ELSE outcome='created';reason='no_candidate'; END IF;
 END IF;
 IF target IS NOT NULL THEN outcome='reconciled'; END IF;
 INSERT INTO public.transaction_source_observations(source_id,idempotency_key,provider_reference,transaction_id,evidence_origin,accepted_payload,payload_fingerprint,source_revision,
 merchant,normalized_merchant,merchant_key,amount_minor,currency_code,amount_basis,movement_type,source_transaction_date,source_charge_date,occurred_at,occurred_at_raw,time_precision,time_width,
 time_verified,reference_verified,date_discrepancy,payment_source_id,source_metadata,outcome,reason_code,review_required,candidate_ids,initial_identity)
 VALUES(s.id,p->>'idempotency_key',nullif(p->'provider_reference','null'),target,'source',p,hash,s.revision,p->>'merchant',n->>'merchant',merchant_key,(n->>'amount_minor')::numeric,'ILS','accounting',p->>'movement_type',
 (n->>'date')::date,(p->>'charge_date')::date,(n->>'instant')::timestamptz,p->>'occurred_at',n->>'precision',(n->>'width')::interval,time_valid,ref_verified,
 coalesce(((n->>'instant')::timestamptz AT TIME ZONE 'Asia/Jerusalem')::date<>(n->>'date')::date,false),payment,p->'source_metadata',
 CASE WHEN outcome='created' THEN 'ambiguous' ELSE outcome END,reason,outcome IN ('ambiguous','conflict'),candidate_ids,
 CASE WHEN target IS NOT NULL THEN (SELECT public.apy_identity(tx) FROM public.transactions tx WHERE tx.id=target) END) RETURNING * INTO o;
 IF outcome='created' THEN target=public.apy_create_cash(o.id); UPDATE public.transaction_source_observations SET outcome='created' WHERE id=o.id;
 ELSIF outcome='reconciled' AND s.source_kind='cal' AND NOT public.apy_enrich(o.id,(p->>'charge_date')::date) THEN
  UPDATE public.transaction_source_observations SET review_required=true,reason_code='enrichment_conflict' WHERE id=o.id;
 END IF;
 INSERT INTO public.transaction_reconciliation_events(source_id,observation_id,event_kind,transaction_id,actor,reason_code,decision_revision,evidence)
 VALUES(s.id,o.id,outcome,target,'source',reason,1,jsonb_build_object('candidate_ids',candidate_ids,'source_revision',s.revision::text));
 RETURN public.apy_result(o.id);
END $$;
CREATE OR REPLACE FUNCTION public.apy_receipt(p_key UUID,p_hash TEXT) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE e public.transaction_reconciliation_events%ROWTYPE;
BEGIN
 SELECT * INTO e FROM public.transaction_reconciliation_events WHERE request_key=p_key;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF e.command_fingerprint<>p_hash THEN RETURN public.apy_rejected('command_key_conflict')||jsonb_build_object('outcome','conflict','review_required',true); END IF;
 RETURN e.result||jsonb_build_object('replayed',true);
END $$;

CREATE OR REPLACE FUNCTION public.configure_ingestion_source(p_request_key UUID,p_command JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE s public.transaction_ingestion_sources%ROWTYPE; cfg JSONB; oldcfg JSONB; x JSONB; k TEXT; h TEXT; result JSONB;
BEGIN
 LOCK TABLE public.transactions IN EXCLUSIVE MODE;
 IF p_request_key IS NULL THEN RAISE EXCEPTION 'request_key_required' USING ERRCODE='22023'; END IF;
 PERFORM public.apy_keys(p_command,ARRAY['source_kind','instance_key','is_active','expected_revision','configuration','actor']);
 h=public.apy_hash(jsonb_build_object('command','configure', 'payload',p_command)); result=public.apy_receipt(p_request_key,h); IF result IS NOT NULL THEN RETURN result; END IF;
 cfg=coalesce(p_command->'configuration','{}');
 PERFORM public.apy_keys(cfg,ARRAY['payment_source_ids','card_mappings','aliases','time_verified','verified_references']);
 IF octet_length(cfg::text)>32768 OR coalesce(p_command->>'actor','')='' OR length(p_command->>'actor')>255 THEN RAISE EXCEPTION 'invalid_configuration' USING ERRCODE='22023'; END IF;
 IF cfg ? 'time_verified' AND jsonb_typeof(cfg->'time_verified')<>'boolean' THEN RAISE EXCEPTION 'invalid_configuration' USING ERRCODE='22023'; END IF;
 FOREACH k IN ARRAY ARRAY['payment_source_ids','card_mappings','aliases','verified_references'] LOOP
  IF cfg ? k AND (jsonb_typeof(cfg->k)<>'array' OR jsonb_array_length(cfg->k)>100) THEN RAISE EXCEPTION 'invalid_configuration' USING ERRCODE='22023'; END IF;
 END LOOP;
 FOR x IN SELECT * FROM jsonb_array_elements(coalesce(cfg->'payment_source_ids','[]')) LOOP
  IF jsonb_typeof(x)<>'string' OR x#>>'{}' !~ '^[1-9]\d{0,18}$' OR NOT EXISTS(SELECT 1 FROM public.payment_sources WHERE id=(x#>>'{}')::bigint) THEN RAISE EXCEPTION 'invalid_payment_source' USING ERRCODE='22023'; END IF;
 END LOOP;
 FOR x IN SELECT * FROM jsonb_array_elements(coalesce(cfg->'card_mappings','[]')) LOOP
  PERFORM public.apy_keys(x,ARRAY['card_reference','payment_source_id']);
  IF coalesce(length(x->>'card_reference'),0) NOT BETWEEN 1 AND 255 OR NOT coalesce(cfg->'payment_source_ids','[]') ? (x->>'payment_source_id') THEN RAISE EXCEPTION 'invalid_card_mapping' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(cfg->'card_mappings','[]')) mappings(item) GROUP BY item->>'card_reference' HAVING count(*)>1) THEN RAISE EXCEPTION 'conflicting_card_mapping' USING ERRCODE='22023'; END IF;
 FOR x IN SELECT * FROM jsonb_array_elements(coalesce(cfg->'aliases','[]')) LOOP
  PERFORM public.apy_keys(x,ARRAY['merchant','key','payment_source_id']);
  IF coalesce(length(x->>'merchant'),0) NOT BETWEEN 1 AND 512 OR public.apy_merchant(x->>'merchant')='' OR coalesce(length(x->>'key'),0) NOT BETWEEN 1 AND 255
  OR (x->>'payment_source_id' IS NOT NULL AND NOT coalesce(cfg->'payment_source_ids','[]') ? (x->>'payment_source_id')) THEN RAISE EXCEPTION 'invalid_alias' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(cfg->'aliases','[]')) a CROSS JOIN jsonb_array_elements(coalesce(cfg->'aliases','[]')) b
 WHERE a<>b AND public.apy_merchant(a->>'merchant')=public.apy_merchant(b->>'merchant') AND (a->>'payment_source_id' IS NULL OR b->>'payment_source_id' IS NULL OR a->>'payment_source_id'=b->>'payment_source_id') AND a->>'key'<>b->>'key') THEN RAISE EXCEPTION 'conflicting_alias' USING ERRCODE='22023'; END IF;
 FOR x IN SELECT * FROM jsonb_array_elements(coalesce(cfg->'verified_references','[]')) LOOP
  PERFORM public.apy_keys(x,ARRAY['provider','type','scope']);
  FOREACH k IN ARRAY ARRAY['provider','type','scope'] LOOP IF jsonb_typeof(x->k) IS DISTINCT FROM 'string' OR length(x->>k) NOT BETWEEN 1 AND 255 THEN RAISE EXCEPTION 'invalid_reference_profile' USING ERRCODE='22023'; END IF; END LOOP;
 END LOOP;
 IF p_command->>'source_kind'='legacy_api' THEN RAISE EXCEPTION 'reserved_legacy_source' USING ERRCODE='22023'; END IF;
 SELECT * INTO s FROM public.transaction_ingestion_sources WHERE source_kind=p_command->>'source_kind' AND instance_key=p_command->>'instance_key' FOR UPDATE;
 IF FOUND THEN
  IF s.revision IS DISTINCT FROM (p_command->>'expected_revision')::bigint THEN RAISE EXCEPTION 'stale_source_revision' USING ERRCODE='40001'; END IF;
  oldcfg=s.configuration;
  UPDATE public.transaction_ingestion_sources SET configuration=cfg,is_active=coalesce((p_command->>'is_active')::boolean,true),revision=revision+1,updated_at=clock_timestamp() WHERE id=s.id RETURNING * INTO s;
 ELSE
  IF p_command->>'expected_revision' IS NOT NULL THEN RAISE EXCEPTION 'stale_source_revision' USING ERRCODE='40001'; END IF;
  INSERT INTO public.transaction_ingestion_sources(source_kind,instance_key,is_active,configuration) VALUES(p_command->>'source_kind',p_command->>'instance_key',coalesce((p_command->>'is_active')::boolean,true),cfg) RETURNING * INTO s;
 END IF;
 result=jsonb_build_object('source_id',s.id::text,'revision',s.revision::text,'replayed',false);
 INSERT INTO public.transaction_reconciliation_events(source_id,event_kind,request_key,command_fingerprint,actor,reason_code,evidence,result)
 VALUES(s.id,'source_configuration',p_request_key,h,p_command->>'actor','approved_configuration',jsonb_build_object('before',oldcfg,'after',cfg,'revision',s.revision::text),result);
 RETURN result;
END $$;
