CREATE OR REPLACE FUNCTION public.apy_date(p TEXT) RETURNS DATE LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE d DATE;
BEGIN
 IF p !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'invalid_date' USING ERRCODE='22023'; END IF;
 d=p::date;
 IF NOT isfinite(d) OR to_char(d,'YYYY-MM-DD')<>p THEN RAISE EXCEPTION 'invalid_date' USING ERRCODE='22023'; END IF;
 RETURN d;
END $$;
CREATE OR REPLACE FUNCTION public.apy_identity(t public.transactions) RETURNS JSONB LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT jsonb_build_object('amount',t.total_amount,'movement_type',t.movement_type,'currency',t.currency,
 'original_amount',t.original_amount,'exchange_rate',t.exchange_rate,'transaction_date',t.transaction_date,
 'payment_source_id',t.payment_source_id::text);
$$;
CREATE OR REPLACE FUNCTION public.apy_cash_fingerprint(p_id INTEGER) RETURNS TEXT LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT md5((to_jsonb(t)-ARRAY['updated_at','voided_at','void_request_key','void_fingerprint','void_reason'])::text) FROM public.transactions t WHERE id=p_id;
$$;
CREATE OR REPLACE FUNCTION public.apy_protected(p_id INTEGER) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT t.loan_id IS NOT NULL OR t.parent_transaction_id IS NOT NULL OR coalesce(t.installment_count,1)>1
 OR t.installment_number IS NOT NULL OR t.installments_info IS NOT NULL OR coalesce(t.global_discount,0)<>0
 OR t.currency IS DISTINCT FROM 'ILS' OR coalesce(t.original_amount,0)<>0 OR coalesce(t.exchange_rate,0)<>0
 OR EXISTS(SELECT 1 FROM public.savings_entries WHERE transaction_id=t.id)
 OR EXISTS(SELECT 1 FROM public.loan_payments WHERE transaction_id=t.id)
 OR EXISTS(SELECT 1 FROM public.transaction_items WHERE transaction_id=t.id)
 OR EXISTS(SELECT 1 FROM public.lego_sets WHERE transaction_id=t.id)
 OR EXISTS(SELECT 1 FROM public.shopping_checkouts WHERE transaction_id=t.id)
 OR EXISTS(SELECT 1 FROM public.transactions WHERE parent_transaction_id=t.id)
 OR EXISTS(SELECT 1 FROM public.categories WHERE id=t.category_id AND savings_role IS NOT NULL)
 FROM public.transactions t WHERE t.id=p_id;
$$;
CREATE OR REPLACE FUNCTION public.apy_captured(p_id INTEGER) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM public.transactions t JOIN public.budget_months m ON m.month_start=date_trunc('month',t.transaction_date)::date
 WHERE t.id=p_id AND (EXISTS(SELECT 1 FROM public.budget_operations o WHERE o.budget_month_id=m.id AND o.operation_type='month_close')
 OR EXISTS(SELECT 1 FROM public.budget_operation_items i WHERE i.budget_month_id=m.id AND i.item_kind IN ('carryover','unused_disposition'))));
$$;
CREATE OR REPLACE FUNCTION public.apy_result(p_id BIGINT, p_replay BOOLEAN DEFAULT false) RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT jsonb_build_object('outcome',CASE WHEN p_replay THEN 'already_observed' ELSE o.outcome END,
 'original_outcome',CASE WHEN p_replay THEN o.outcome END,'observation_id',o.id::text,'transaction_id',o.transaction_id::text,
 'disposition',CASE WHEN t.voided_at IS NOT NULL THEN 'cancelled' WHEN o.transaction_id IS NULL THEN 'pending' WHEN o.outcome='created' THEN 'created' ELSE 'attached' END,
 'review_required',o.review_required,'reason_code',o.reason_code,'replayed',p_replay,'decision_revision',o.decision_revision::text)
 FROM public.transaction_source_observations o LEFT JOIN public.transactions t ON t.id=o.transaction_id WHERE o.id=p_id;
$$;
CREATE OR REPLACE FUNCTION public.apy_rejected(p_reason TEXT) RETURNS JSONB LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT jsonb_build_object('outcome','rejected','original_outcome',NULL,'observation_id',NULL,'transaction_id',NULL,'disposition','pending',
 'review_required',false,'reason_code',p_reason,'replayed',false,'decision_revision',NULL);
$$;

-- Recomputed in SQL even for private RPC callers; no normalized client fields trusted.
CREATE OR REPLACE FUNCTION public.apy_normalize(p JSONB) RETURNS JSONB LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE n JSONB; k TEXT; v JSONB; ts TEXT; r TEXT[]; precision TEXT; width TEXT; instant TIMESTAMPTZ; d DATE; amount NUMERIC;
BEGIN
 PERFORM public.apy_keys(p,ARRAY['idempotency_key','provider_reference','merchant','accounting_amount','currency','movement_type','transaction_date',
 'occurred_at','charge_date','payment_source_id','payment_evidence','category_id','source_metadata','original_amount','original_currency','original_scale']);
 IF jsonb_typeof(p->'idempotency_key') IS DISTINCT FROM 'string' OR length(p->>'idempotency_key') NOT BETWEEN 1 AND 255
 OR p->>'idempotency_key'<>btrim(p->>'idempotency_key') THEN RAISE EXCEPTION 'invalid_idempotency_key' USING ERRCODE='22023'; END IF;
 IF jsonb_typeof(p->'accounting_amount') IS DISTINCT FROM 'string' OR p->>'accounting_amount' !~ '^\d{1,28}(\.\d{1,2})?$' THEN RAISE EXCEPTION 'invalid_accounting_amount' USING ERRCODE='22023'; END IF;
 amount=(p->>'accounting_amount')::numeric;
 IF amount<=0 THEN RAISE EXCEPTION 'invalid_accounting_amount' USING ERRCODE='22023'; END IF;
 IF p->>'currency' IS DISTINCT FROM 'ILS' THEN RAISE EXCEPTION 'accounting_amount_required' USING ERRCODE='22023'; END IF;
 IF coalesce(p->>'movement_type','') NOT IN ('expense','income') THEN RAISE EXCEPTION 'unsupported_event_kind' USING ERRCODE='22023'; END IF;
 IF jsonb_typeof(p->'merchant') IS DISTINCT FROM 'string' OR length(p->>'merchant') NOT BETWEEN 1 AND 512 OR public.apy_merchant(p->>'merchant')='' THEN RAISE EXCEPTION 'invalid_merchant' USING ERRCODE='22023'; END IF;
 FOREACH k IN ARRAY ARRAY['payment_source_id','category_id'] LOOP
  IF p->>k IS NOT NULL AND (jsonb_typeof(p->k)<>'string' OR p->>k !~ '^[1-9]\d{0,18}$') THEN RAISE EXCEPTION 'invalid_identifier' USING ERRCODE='22023'; END IF;
  IF p->>k IS NOT NULL THEN PERFORM (p->>k)::bigint; END IF;
 END LOOP;
 IF p->>'provider_reference' IS NOT NULL THEN
  PERFORM public.apy_keys(p->'provider_reference',ARRAY['provider','type','scope','value']);
  FOREACH k IN ARRAY ARRAY['provider','type','scope','value'] LOOP
   IF jsonb_typeof(p->'provider_reference'->k) IS DISTINCT FROM 'string' OR length(p->'provider_reference'->>k) NOT BETWEEN 1 AND 255 THEN RAISE EXCEPTION 'invalid_provider_reference' USING ERRCODE='22023'; END IF;
  END LOOP;
 END IF;
 PERFORM public.apy_keys(coalesce(nullif(p->'payment_evidence','null'),'{}'),ARRAY['card_reference','last4','issuer','method','owner','name']);
 FOR k,v IN SELECT * FROM jsonb_each(coalesce(nullif(p->'payment_evidence','null'),'{}')) LOOP
  IF jsonb_typeof(v)<>'string' OR length(v#>>'{}') NOT BETWEEN 1 AND 255 OR (k='last4' AND v#>>'{}' !~ '^\d{4}$') THEN RAISE EXCEPTION 'invalid_payment_evidence' USING ERRCODE='22023'; END IF;
 END LOOP;
 PERFORM public.apy_keys(coalesce(nullif(p->'source_metadata','null'),'{}'),ARRAY['provider_status','channel','terminal_reference']);
 IF octet_length(coalesce(p->'source_metadata','{}')::text)>8192 THEN RAISE EXCEPTION 'metadata_too_large' USING ERRCODE='22023'; END IF;
 FOR k,v IN SELECT * FROM jsonb_each(coalesce(nullif(p->'source_metadata','null'),'{}')) LOOP
  IF jsonb_typeof(v)<>'string' OR length(v#>>'{}')>255 THEN RAISE EXCEPTION 'invalid_metadata' USING ERRCODE='22023'; END IF;
 END LOOP;
 ts=p->>'occurred_at';
 IF ts IS NOT NULL THEN
  r=regexp_match(ts,'^(\d{4}-\d{2}-\d{2})T([01]\d|2[0-3]):([0-5]\d)(:([0-5]\d)(\.(\d{1,6}))?)?(Z|[+-](0\d|1[0-4]):[0-5]\d)?$');
  IF r IS NULL OR length(ts)>80 OR ts~'[+-]14:(?!00)' THEN RAISE EXCEPTION 'invalid_occurred_at' USING ERRCODE='22023'; END IF;
  PERFORM public.apy_date(r[1]);
  precision=CASE WHEN r[7] IS NOT NULL THEN 'fractional_'||length(r[7]) WHEN r[5] IS NOT NULL THEN 'second' ELSE 'minute' END;
  width=CASE WHEN r[7] IS NOT NULL THEN (1/power(10::numeric,length(r[7])))::text||' seconds' WHEN r[5] IS NOT NULL THEN '1 second' ELSE '1 minute' END;
  IF r[8] IS NOT NULL THEN instant=ts::timestamptz; END IF;
 END IF;
 d=CASE WHEN p->>'transaction_date' IS NOT NULL THEN public.apy_date(p->>'transaction_date') ELSE (instant AT TIME ZONE 'Asia/Jerusalem')::date END;
 IF d IS NULL THEN RAISE EXCEPTION 'transaction_date_required' USING ERRCODE='22023'; END IF;
 IF p->>'charge_date' IS NOT NULL THEN PERFORM public.apy_date(p->>'charge_date'); END IF;
 IF p->>'original_amount' IS NOT NULL THEN
  IF jsonb_typeof(p->'original_amount')<>'string' OR p->>'original_amount' !~ '^\d{1,28}(\.\d{1,6})?$'
  OR (p->>'original_amount')::numeric<=0 OR coalesce(p->>'original_currency','') !~ '^[A-Z]{3}$'
  OR coalesce(p->>'original_scale','') !~ '^[0-6]$' THEN RAISE EXCEPTION 'invalid_original_amount' USING ERRCODE='22023'; END IF;
  IF length(split_part(p->>'original_amount','.',2))>(p->>'original_scale')::integer THEN RAISE EXCEPTION 'invalid_original_amount' USING ERRCODE='22023'; END IF;
 ELSIF p->>'original_currency' IS NOT NULL OR p->>'original_scale' IS NOT NULL THEN RAISE EXCEPTION 'invalid_original_amount' USING ERRCODE='22023'; END IF;
 n=jsonb_build_object('idempotency_key',p->>'idempotency_key','provider_reference',p->'provider_reference','merchant',p->>'merchant',
 'accounting_amount',trunc(amount)::text||'.'||lpad(mod(amount*100,100)::integer::text,2,'0'),'currency','ILS','movement_type',p->>'movement_type',
 'transaction_date',p->>'transaction_date','occurred_at',ts,'charge_date',p->>'charge_date','payment_source_id',p->>'payment_source_id',
 'category_id',p->>'category_id','payment_evidence',coalesce(nullif(p->'payment_evidence','null'),'{}'),'source_metadata',coalesce(nullif(p->'source_metadata','null'),'{}'),
 'original_amount',p->>'original_amount','original_currency',p->>'original_currency','original_scale',p->>'original_scale');
 RETURN jsonb_build_object('input',n,'amount_minor',trunc(amount*100)::text,'date',d,'instant',instant,'precision',precision,'width',width,'merchant',public.apy_merchant(p->>'merchant'));
END $$;

CREATE OR REPLACE FUNCTION public.apy_append_only() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN RAISE EXCEPTION 'APY audit events are append-only' USING ERRCODE='23514'; END $$;
DROP TRIGGER IF EXISTS apy_events_immutable ON public.transaction_reconciliation_events;
CREATE TRIGGER apy_events_immutable BEFORE UPDATE OR DELETE ON public.transaction_reconciliation_events FOR EACH ROW EXECUTE FUNCTION public.apy_append_only();

CREATE OR REPLACE FUNCTION public.apy_observation_guard() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.evidence_origin='source' THEN RAISE EXCEPTION 'APY observation identity is retained' USING ERRCODE='23514'; END IF;
  RETURN OLD;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['transaction_id','outcome','reason_code','review_required','decision_revision','candidate_ids','initial_identity','charge_date_origin','identity_overridden','charge_date_overridden'])
  IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['transaction_id','outcome','reason_code','review_required','decision_revision','candidate_ids','initial_identity','charge_date_origin','identity_overridden','charge_date_overridden']) THEN
  RAISE EXCEPTION 'APY accepted evidence and receipt time are immutable' USING ERRCODE='23514'; END IF;
 IF (OLD.identity_overridden AND NOT NEW.identity_overridden) OR (OLD.charge_date_overridden AND NOT NEW.charge_date_overridden) OR NEW.decision_revision<OLD.decision_revision THEN
  RAISE EXCEPTION 'APY override flags and revisions cannot go backwards' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS apy_observations_immutable ON public.transaction_source_observations;
CREATE TRIGGER apy_observations_immutable BEFORE UPDATE OR DELETE ON public.transaction_source_observations FOR EACH ROW EXECUTE FUNCTION public.apy_observation_guard();

INSERT INTO public.transaction_ingestion_sources(source_kind,instance_key,configuration)
VALUES('legacy_api','default','{}') ON CONFLICT(source_kind,instance_key) DO NOTHING;
CREATE OR REPLACE FUNCTION public.apy_mirror_cash(p_id INTEGER,p_origin TEXT) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE t public.transactions%ROWTYPE; sid BIGINT; p JSONB;
BEGIN
 SELECT * INTO t FROM public.transactions WHERE id=p_id;
 IF t.external_id IS NULL OR t.external_id='' THEN RETURN; END IF;
 SELECT id INTO sid FROM public.transaction_ingestion_sources WHERE source_kind='legacy_api' AND instance_key='default';
 p=jsonb_build_object('external_id',t.external_id,'identity',public.apy_identity(t));
 INSERT INTO public.transaction_source_observations(source_id,idempotency_key,transaction_id,evidence_origin,accepted_payload,payload_fingerprint,source_revision,
 merchant,normalized_merchant,amount_minor,currency_code,amount_basis,movement_type,source_transaction_date,source_charge_date,payment_source_id,outcome,reason_code,initial_identity)
 VALUES(sid,t.external_id,t.id,p_origin,p,public.apy_hash(p),1,left(t.description,512),public.apy_merchant(left(t.description,512)),
 CASE WHEN t.total_amount>0 AND t.total_amount*100=trunc(t.total_amount*100) AND abs(t.total_amount)<1e28 THEN t.total_amount*100 END,
 NULL,'legacy_unknown',t.movement_type,t.transaction_date,t.charge_date,t.payment_source_id,'legacy_unverified',p_origin,public.apy_identity(t))
 ON CONFLICT(source_id,idempotency_key) DO NOTHING;
END $$;
CREATE OR REPLACE FUNCTION public.apy_legacy_mirror_trigger() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN PERFORM public.apy_mirror_cash(NEW.id,'legacy_insert'); RETURN NEW; END $$;
DROP TRIGGER IF EXISTS apy_legacy_mirror ON public.transactions;
CREATE TRIGGER apy_legacy_mirror AFTER INSERT OR UPDATE OF external_id ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.apy_legacy_mirror_trigger();

CREATE OR REPLACE FUNCTION public.apy_transaction_guard() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE o RECORD; identity_changed BOOLEAN; charge_changed BOOLEAN; enriched BOOLEAN;
BEGIN
 IF TG_OP='DELETE' OR NEW.external_id IS DISTINCT FROM OLD.external_id THEN
  IF EXISTS(SELECT 1 FROM public.transaction_source_observations ob WHERE ob.transaction_id=OLD.id AND
   (ob.evidence_origin='source' OR EXISTS(SELECT 1 FROM public.transaction_reconciliation_events WHERE observation_id=ob.id))) THEN
   RAISE EXCEPTION 'APY-managed history requires explicit cancellation; external identity is reserved' USING ERRCODE='23514'; END IF;
  DELETE FROM public.transaction_source_observations WHERE transaction_id=OLD.id AND evidence_origin IN ('legacy_backfill','legacy_insert');
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 END IF;
 identity_changed=public.apy_identity(OLD) IS DISTINCT FROM public.apy_identity(NEW);
 charge_changed=OLD.charge_date IS DISTINCT FROM NEW.charge_date;
 enriched=charge_changed AND NOT identity_changed AND EXISTS(SELECT 1 FROM public.transaction_reconciliation_events
  WHERE transaction_id=OLD.id AND event_kind='enrichment' AND evidence->>'charge_date'=NEW.charge_date::text AND xmin::text=pg_current_xact_id()::text);
 IF identity_changed OR (charge_changed AND NOT enriched) THEN
  FOR o IN SELECT * FROM public.transaction_source_observations WHERE transaction_id=OLD.id AND evidence_origin='source' ORDER BY id LOOP
   UPDATE public.transaction_source_observations SET identity_overridden=identity_overridden OR identity_changed,
    charge_date_overridden=charge_date_overridden OR (charge_changed AND NOT enriched),decision_revision=decision_revision+1 WHERE id=o.id;
   INSERT INTO public.transaction_reconciliation_events(source_id,observation_id,event_kind,transaction_id,actor,reason_code,decision_revision,evidence)
   VALUES(o.source_id,o.id,'user_edit',OLD.id,'user_or_unknown','canonical_override',o.decision_revision+1,
    jsonb_build_object('before',public.apy_identity(OLD),'after',public.apy_identity(NEW),'charge_changed',charge_changed));
  END LOOP;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS apy_guard_transaction ON public.transactions;
CREATE TRIGGER apy_guard_transaction BEFORE UPDATE OR DELETE ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.apy_transaction_guard();

CREATE OR REPLACE FUNCTION public.apy_cancel_authorized(p_id INTEGER,p_key UUID,p_hash TEXT) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT NOT public.apy_protected(p_id) AND NOT public.apy_captured(p_id) AND EXISTS(
 SELECT 1 FROM public.transaction_reconciliation_events e JOIN public.transaction_source_observations o ON o.id=e.observation_id
 WHERE e.transaction_id=p_id AND e.event_kind='cancel' AND e.request_key=p_key AND e.command_fingerprint=p_hash
 AND e.xmin::text=pg_current_xact_id()::text AND o.transaction_id=p_id AND o.evidence_origin='source');
$$;

CREATE OR REPLACE FUNCTION public.cancel_ingested_transaction(p_request_key UUID,p_command JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE o public.transaction_source_observations%ROWTYPE; t public.transactions%ROWTYPE; h TEXT; result JSONB;
BEGIN
 LOCK TABLE public.transactions IN EXCLUSIVE MODE;
 PERFORM public.apy_keys(p_command,ARRAY['transaction_id','expected_revision','expected_transaction_fingerprint','reason','actor']);
 IF p_request_key IS NULL OR coalesce(length(p_command->>'reason'),0) NOT BETWEEN 1 AND 500 OR coalesce(length(p_command->>'actor'),0) NOT BETWEEN 1 AND 255 THEN RAISE EXCEPTION 'invalid_cancel_command' USING ERRCODE='22023'; END IF;
 h=public.apy_hash(jsonb_build_object('command','cancel','payload',p_command));result=public.apy_receipt(p_request_key,h);IF result IS NOT NULL THEN RETURN result; END IF;
 SELECT * INTO t FROM public.transactions WHERE id=(p_command->>'transaction_id')::integer FOR UPDATE;
 SELECT * INTO o FROM public.transaction_source_observations WHERE transaction_id=t.id AND evidence_origin='source' ORDER BY id LIMIT 1 FOR UPDATE;
 IF o.id IS NULL OR t.voided_at IS NOT NULL OR public.apy_protected(t.id) OR public.apy_captured(t.id) THEN RETURN public.apy_rejected('protected_transaction'); END IF;
 IF o.decision_revision IS DISTINCT FROM (p_command->>'expected_revision')::bigint OR public.apy_cash_fingerprint(t.id) IS DISTINCT FROM p_command->>'expected_transaction_fingerprint' THEN RETURN public.apy_result(o.id)||jsonb_build_object('outcome','conflict','review_required',true,'reason_code','stale_review'); END IF;
 UPDATE public.transaction_source_observations SET decision_revision=decision_revision+1 WHERE transaction_id=t.id;
 result=public.apy_result(o.id)||jsonb_build_object('disposition','cancelled','reason_code','owner_cancelled');
 INSERT INTO public.transaction_reconciliation_events(source_id,observation_id,event_kind,request_key,command_fingerprint,transaction_id,actor,reason_code,decision_revision,evidence,result)
 VALUES(o.source_id,o.id,'cancel',p_request_key,h,t.id,p_command->>'actor','owner_cancelled',o.decision_revision+1,jsonb_build_object('reason',p_command->>'reason'),result);
 UPDATE public.transactions SET voided_at=clock_timestamp(),void_request_key=p_request_key,void_fingerprint=h,void_reason=p_command->>'reason' WHERE id=t.id;
 RETURN result;
END $$;

CREATE OR REPLACE FUNCTION public.amend_observation(p_request_key UUID,p_command JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE o public.transaction_source_observations%ROWTYPE; h TEXT; result JSONB; ok BOOLEAN=true; d DATE; sid BIGINT;
BEGIN
 LOCK TABLE public.transactions IN EXCLUSIVE MODE;
 PERFORM public.apy_keys(p_command,ARRAY['source_id','observation_id','expected_revision','charge_date','actor']);
 IF p_request_key IS NULL OR coalesce(length(p_command->>'actor'),0) NOT BETWEEN 1 AND 255 THEN RAISE EXCEPTION 'invalid_amendment' USING ERRCODE='22023'; END IF;
 h=public.apy_hash(jsonb_build_object('command','amend','payload',p_command));result=public.apy_receipt(p_request_key,h);IF result IS NOT NULL THEN RETURN result; END IF;
 sid=(p_command->>'source_id')::bigint;
 IF NOT EXISTS(SELECT 1 FROM public.transaction_ingestion_sources WHERE id=sid AND is_active AND source_kind='cal') THEN RETURN public.apy_rejected('source_unavailable'); END IF;
 SELECT * INTO o FROM public.transaction_source_observations WHERE id=(p_command->>'observation_id')::bigint AND source_id=sid AND evidence_origin='source' FOR UPDATE;
 IF o.id IS NULL THEN RETURN public.apy_rejected('observation_not_found'); END IF;
 IF o.decision_revision IS DISTINCT FROM (p_command->>'expected_revision')::bigint THEN RETURN public.apy_result(o.id)||jsonb_build_object('outcome','conflict','reason_code','stale_review','review_required',true); END IF;
 d=public.apy_date(p_command->>'charge_date');IF d IS NULL THEN RAISE EXCEPTION 'charge_date_required' USING ERRCODE='22023'; END IF;
 -- Accepted input is immutable: amendment lives in the append-only event, so the
 -- original capture payload always remains replayable after a provider update.
 IF o.transaction_id IS NOT NULL THEN ok=public.apy_enrich(o.id,d); END IF;
 UPDATE public.transaction_source_observations SET decision_revision=decision_revision+1,review_required=review_required OR NOT ok,
 reason_code=CASE WHEN ok THEN reason_code ELSE 'enrichment_conflict' END WHERE id=o.id;
 result=public.apy_result(o.id);
 INSERT INTO public.transaction_reconciliation_events(source_id,observation_id,event_kind,request_key,command_fingerprint,transaction_id,actor,reason_code,decision_revision,evidence,result)
 VALUES(o.source_id,o.id,'amendment',p_request_key,h,o.transaction_id,p_command->>'actor',CASE WHEN ok THEN 'charge_date_evidence' ELSE 'enrichment_conflict' END,o.decision_revision+1,jsonb_build_object('charge_date',d),result);
 RETURN result;
END $$;

CREATE OR REPLACE FUNCTION public.resolve_observation(p_request_key UUID,p_command JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE o public.transaction_source_observations%ROWTYPE; t public.transactions%ROWTYPE; h TEXT; result JSONB; target INTEGER; action TEXT; enriched BOOLEAN=true;
BEGIN
 LOCK TABLE public.transactions IN EXCLUSIVE MODE;
 PERFORM public.apy_keys(p_command,ARRAY['observation_id','expected_revision','action','transaction_id','expected_transaction_fingerprint','expected_candidate_fingerprints','reason','actor']);
 action=p_command->>'action';
 IF p_request_key IS NULL OR coalesce(action,'') NOT IN ('link','separate') OR coalesce(length(p_command->>'reason'),0) NOT BETWEEN 1 AND 500 OR coalesce(length(p_command->>'actor'),0) NOT BETWEEN 1 AND 255 THEN RAISE EXCEPTION 'invalid_review_command' USING ERRCODE='22023'; END IF;
 h=public.apy_hash(jsonb_build_object('command','resolve','payload',p_command));result=public.apy_receipt(p_request_key,h);IF result IS NOT NULL THEN RETURN result; END IF;
 SELECT * INTO o FROM public.transaction_source_observations WHERE id=(p_command->>'observation_id')::bigint AND evidence_origin='source' FOR UPDATE;
 IF o.id IS NULL THEN RETURN public.apy_rejected('observation_not_found'); END IF;
 IF o.transaction_id IS NOT NULL OR o.decision_revision IS DISTINCT FROM (p_command->>'expected_revision')::bigint THEN RETURN public.apy_result(o.id)||jsonb_build_object('outcome','conflict','reason_code','stale_review','review_required',true); END IF;
 IF action='link' THEN
  SELECT * INTO t FROM public.transactions WHERE id=(p_command->>'transaction_id')::integer FOR UPDATE;
  IF t.id IS NULL OR t.voided_at IS NOT NULL OR public.apy_protected(t.id) OR public.apy_captured(t.id) THEN RETURN public.apy_rejected('protected_transaction'); END IF;
  IF public.apy_cash_fingerprint(t.id) IS DISTINCT FROM p_command->>'expected_transaction_fingerprint'
   OR t.total_amount*100<>o.amount_minor OR t.movement_type<>o.movement_type OR t.payment_source_id<>o.payment_source_id
   OR abs(t.transaction_date-o.source_transaction_date)>1 OR EXISTS(SELECT 1 FROM public.transaction_source_observations WHERE transaction_id=t.id AND source_id=o.source_id) THEN
   RETURN public.apy_result(o.id)||jsonb_build_object('outcome','conflict','reason_code','review_target_conflict','review_required',true); END IF;
  target=t.id;
  UPDATE public.transaction_source_observations SET transaction_id=t.id,initial_identity=public.apy_identity(t),outcome='reconciled' WHERE id=o.id;
  IF EXISTS(SELECT 1 FROM public.transaction_ingestion_sources WHERE id=o.source_id AND source_kind='cal') THEN
   enriched=public.apy_enrich(o.id,public.apy_charge_evidence(o.id));
  END IF;
 ELSE
  -- Explicit owner decision, never an ingestion fallback for ambiguity.
  IF o.outcome='conflict' THEN RETURN public.apy_rejected('conflict_requires_domain_correction'); END IF;
  IF p_command->'expected_candidate_fingerprints' IS DISTINCT FROM public.apy_review_fingerprints(o.id) THEN RETURN public.apy_result(o.id)||jsonb_build_object('outcome','conflict','reason_code','stale_review','review_required',true); END IF;
  target=public.apy_create_cash(o.id);UPDATE public.transaction_source_observations SET outcome='created' WHERE id=o.id;
 END IF;
 UPDATE public.transaction_source_observations SET decision_revision=decision_revision+1,review_required=NOT enriched,
 reason_code=CASE WHEN enriched THEN 'owner_'||action ELSE 'enrichment_conflict' END WHERE id=o.id;
 result=public.apy_result(o.id);
 INSERT INTO public.transaction_reconciliation_events(source_id,observation_id,event_kind,request_key,command_fingerprint,transaction_id,actor,reason_code,decision_revision,evidence,result)
 VALUES(o.source_id,o.id,'review',p_request_key,h,target,p_command->>'actor','owner_'||action,o.decision_revision+1,jsonb_build_object('reason',p_command->>'reason','previous_candidates',o.candidate_ids),result);
 RETURN result;
END $$;

-- Immutable historical cash is untouched. Entire migration/backfill is atomic;
-- rerun only creates missing mirrors (including IDs whose old receipt predates APY).
DO $$ DECLARE r RECORD; BEGIN
 FOR r IN SELECT id FROM public.transactions WHERE external_id IS NOT NULL AND external_id<>'' ORDER BY id LOOP
  PERFORM public.apy_mirror_cash(r.id,'legacy_backfill');
 END LOOP;
END $$;

-- Preserve final Savings guard; the sole exception requires a private APY
-- cancellation receipt in this transaction and an unprotected ordinary row.
CREATE OR REPLACE FUNCTION public.savings_guard_transaction() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
  IF TG_OP='INSERT' THEN
    IF num_nonnulls(NEW.voided_at,NEW.void_request_key,NEW.void_fingerprint,NEW.void_reason)>0 THEN RAISE EXCEPTION 'לא ניתן ליצור תנועה שבוטלה מראש' USING ERRCODE='23514'; END IF;
    RETURN NEW;
  END IF;
  IF OLD.voided_at IS NOT NULL THEN RAISE EXCEPTION 'תנועה שבוטלה נשמרת לקריאה בלבד' USING ERRCODE='23514'; END IF;
  IF TG_OP='DELETE' THEN
    IF EXISTS (SELECT 1 FROM public.savings_entries WHERE transaction_id=OLD.id) THEN RAISE EXCEPTION 'יש לבטל תנועת חיסכון בפקודה הייעודית; אין למחוק היסטוריה' USING ERRCODE='23514'; END IF;
    RETURN OLD;
  END IF;
  IF EXISTS (SELECT 1 FROM public.savings_entries WHERE transaction_id=OLD.id)
    AND (NEW.transaction_date,NEW.total_amount,NEW.category_id,NEW.payment_source_id,NEW.charge_date,NEW.voided_at) IS DISTINCT FROM
        (OLD.transaction_date,OLD.total_amount,OLD.category_id,OLD.payment_source_id,OLD.charge_date,OLD.voided_at)
    AND (EXISTS (SELECT 1 FROM public.budget_operations o JOIN public.budget_months m ON m.id=o.budget_month_id
      WHERE m.month_start IN (date_trunc('month',OLD.transaction_date)::date,date_trunc('month',NEW.transaction_date)::date) AND o.operation_type='month_close')
      OR EXISTS (SELECT 1 FROM public.budget_operation_items i JOIN public.budget_months m ON m.id=i.budget_month_id
        WHERE m.month_start IN (date_trunc('month',OLD.transaction_date)::date,date_trunc('month',NEW.transaction_date)::date) AND i.item_kind IN ('carryover','unused_disposition'))) THEN
    RAISE EXCEPTION 'התיקון ישנה היסטוריית תקציב שנלכדה; אין לשנות תנועה זו בנתיב הרגיל' USING ERRCODE='23514',DETAIL='SAVINGS_HISTORY_CORRECTION_BLOCKED';
  END IF;
  IF EXISTS(SELECT 1 FROM public.savings_entries WHERE transaction_id=OLD.id AND source_kind='budget_surplus') AND NOT (
    NEW.voided_at IS NOT NULL AND EXISTS(SELECT 1 FROM public.savings_entries e JOIN public.budget_operation_items i ON i.savings_event_id=e.reversed_by_entry_id WHERE e.transaction_id=OLD.id AND e.source_kind='budget_surplus' AND i.item_kind='savings_transfer' AND i.action_kind='reversal')) THEN
    RAISE EXCEPTION 'העברת עודף ניתנת לתיקון רק בביטול מלא דרך היסטוריית התקציב ובסקירה חדשה' USING ERRCODE='23514',DETAIL='SAVINGS_HISTORY_CORRECTION_BLOCKED'; END IF;
  IF NEW.voided_at IS NOT NULL AND ((NOT EXISTS (SELECT 1 FROM public.savings_entries WHERE transaction_id=OLD.id)
    AND NOT public.apy_cancel_authorized(OLD.id,NEW.void_request_key,NEW.void_fingerprint))
    OR (to_jsonb(NEW)-ARRAY['voided_at','void_request_key','void_fingerprint','void_reason','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['voided_at','void_request_key','void_fingerprint','void_reason','updated_at'])) THEN
    RAISE EXCEPTION 'ביטול מחייב תנועת חיסכון שמורה וקבלה תקינה ללא שינוי כספי נוסף' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;

ALTER TABLE public.transaction_ingestion_sources ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.transaction_source_observations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.transaction_reconciliation_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.transaction_ingestion_sources, public.transaction_source_observations, public.transaction_reconciliation_events FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON SEQUENCE public.transaction_ingestion_sources_id_seq, public.transaction_source_observations_id_seq, public.transaction_reconciliation_events_id_seq FROM PUBLIC,anon,authenticated,service_role;
DO $grants$ DECLARE f RECORD; BEGIN
 FOR f IN SELECT oid::regprocedure signature,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND
 (proname LIKE 'apy_%' OR proname IN ('configure_ingestion_source','ingest_observation','amend_observation','resolve_observation','cancel_ingested_transaction','get_ingestion_observation')) LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,service_role',f.signature);
  IF f.proname NOT LIKE 'apy_%' THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',f.signature); END IF;
 END LOOP;
END $grants$;
COMMIT;
